import { inject } from '@adonisjs/core';
import StartTotpEnrollment from '#identity/actions/start_totp_enrollment';
import type { HttpContext } from '@adonisjs/core/http';

@inject()
export default class StartTotpEnrollmentController {
	constructor(private readonly startTotpEnrollment: StartTotpEnrollment) {}

	/**
	 * Step one is static on purpose: the secret is generated by `execute`, so
	 * refreshing this page never rotates a secret the user is scanning.
	 */
	async render({ inertia }: HttpContext) {
		return inertia.render('settings/two-factor/start', {});
	}

	async execute({ auth, response }: HttpContext) {
		await this.startTotpEnrollment.execute(auth.getUserOrFail());

		return response.redirect().toRoute('two_factor.verify.render');
	}
}
